package com.lucento.app.core.banks

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.text.Normalizer
import java.util.Locale

/**
 * One bank, digital bank or payment platform from the bundled registry (assets/banks/institutions.json, generated by
 * tools/institutions/build_institutions.py from the bank asset library and the wallet design system). Display only:
 * linking a wallet to an institution changes how it looks, never how its money is counted.
 */
@Serializable
data class Institution(
    /** "<iso2>_<slug>", e.g. "ph_bdo". Stored on the wallet ([com.lucento.app.domain.Wallet.institutionId]). */
    val id: String,
    val name: String,
    /** ISO 3166-1 alpha-2. */
    val country: String,
    val type: String,
    /** Brand primary colour (#RRGGBB). */
    val brand: String,
    val card: CardFace,
    val icon: IconSpec,
)

/** How a wallet card looks for this institution; colours were contrast-checked when the registry was generated. */
@Serializable
data class CardFace(
    /** premium_dark, minimal_light, brand_gradient, minimal_brand_accent, glass or monochrome. */
    val template: String,
    /** Gradient stops (#RRGGBB), drawn at [angle] degrees. */
    val stops: List<String>,
    val angle: Int = 135,
    val accent: String,
    /** Text colour on the face; ≥ 4.5:1 against every stop. */
    val ink: String,
    @SerialName("muted_alpha") val mutedAlpha: Float,
    /** Null when the institution has no usable logo; [monogram] is shown instead. */
    val logo: CardLogo? = null,
    val monogram: Monogram,
)

@Serializable
data class CardLogo(
    /** wide (a wordmark, 22dp tall) or square/icon (a 30dp mark with the name beside it). */
    val slot: String,
    /** light: on a white plate; dark: on a navy plate; none: directly on the face. */
    val plate: String,
    /** A white wordmark: never on a white plate. */
    val white: Boolean = false,
    /** Only for monochrome-only source logos; real colour logos are never recoloured. */
    val tint: String? = null,
)

@Serializable
data class Monogram(val text: String, val bg: String, val fg: String)

/** The square list icon: an official app icon, a vector mark on a tile, or a monogram. */
@Serializable
data class IconSpec(
    /** vector, bitmap or monogram. */
    val kind: String,
    @SerialName("tile_bg") val tileBg: String? = null,
    @SerialName("tile_border") val tileBorder: String? = null,
    @SerialName("padding_pct") val paddingPct: Int = 0,
    @SerialName("white_mark") val whiteMark: Boolean = false,
    val monogram: Monogram? = null,
)

@Serializable
private data class InstitutionFile(@SerialName("schema_version") val schemaVersion: Int, val institutions: List<Institution>)

/** The parsed registry: lookup by id and the picker's search. Pure Kotlin, so it is tested on the JVM. */
class InstitutionRegistry(val all: List<Institution>) {
    private val byId = all.associateBy { it.id }
    private val keys = all.associate { it.id to searchKey(it.name) }

    operator fun get(id: String?): Institution? = id?.let(byId::get)

    /** Countries that have at least one institution, most institutions first. */
    val countries: List<String> = all.groupingBy { it.country }.eachCount().entries
        .sortedWith(compareByDescending<Map.Entry<String, Int>> { it.value }.thenBy { it.key }).map { it.key }

    /**
     * Institutions matching [query] (accent- and case-insensitive; every word must match the start of a word in the
     * name, or the id's slug). With a [country], its institutions come first. A blank query lists that country (or
     * everything) alphabetically.
     */
    fun search(query: String, country: String? = null): List<Institution> {
        val words = searchKey(query).split(' ').filter { it.isNotEmpty() }
        val matches = if (words.isEmpty()) {
            if (country != null) all.filter { it.country == country } else all
        } else {
            all.filter { inst ->
                val nameWords = keys.getValue(inst.id).split(' ')
                val slug = inst.id.substringAfter('_')
                words.all { w -> nameWords.any { it.startsWith(w) } || slug.startsWith(w.replace(' ', '_')) }
            }
        }
        return matches.sortedWith(
            compareBy<Institution> { if (country != null && it.country == country) 0 else 1 }
                .thenBy { if (words.isNotEmpty() && keys.getValue(it.id).startsWith(words.first())) 0 else 1 }
                .thenBy { keys.getValue(it.id) }
                .thenBy { it.country }
        )
    }

    companion object {
        private val json = Json { ignoreUnknownKeys = true }

        fun parse(text: String): InstitutionRegistry = InstitutionRegistry(json.decodeFromString(InstitutionFile.serializer(), text).institutions)

        val EMPTY = InstitutionRegistry(emptyList())

        internal fun searchKey(text: String): String =
            Normalizer.normalize(text, Normalizer.Form.NFD).replace(Regex("\\p{M}+"), "")
                .lowercase(Locale.ROOT).replace(Regex("[^a-z0-9]+"), " ").trim()
    }
}
